-- Installments already due (loan sheet as of 14 Nov 2026), derived from the schedules above.
-- Before 2026-08-11 (no cash sheet yet): one entry per loan.
insert into public.loan_payments (id, loan_id, entry_type, date, amount, principal, interest, bank, cash_key, note, recorded_by)
select 'lpay-imp-' || substr(s.loan_id, 6) || '-pre', s.loan_id, 'payment', max(s.due_date), sum(s.amount), sum(s.principal), sum(s.interest),
       coalesce(l.paid_from, ''), null, 'Paid before FabHub: installments 1–' || count(*) || ' per the loan sheet (as of 14 Nov 2026)', 'Loan sheet import'
from public.loan_schedule s join public.loans l on l.id = s.loan_id
where s.id like 'lsch-%' and s.due_date < date '2026-08-11'
group by s.loan_id, l.paid_from
on conflict (id) do nothing;
-- 2026-08-11 to 2026-11-15: one entry per installment, marked not on the cash sheet.
insert into public.loan_payments (id, loan_id, entry_type, date, amount, principal, interest, bank, cash_key, note, recorded_by)
select 'lpay-imp-' || substr(s.loan_id, 6) || '-' || lpad(s.seq::text, 2, '0'), s.loan_id, 'payment', s.due_date, s.amount, s.principal, s.interest,
       coalesce(l.paid_from, ''), null,
       'Installment ' || s.seq || ': paid per the loan sheet (as of 14 Nov 2026), ' ||
       case l.paid_from when 'security' then 'debited from the Security Bank account' when 'metro' then 'paid from Metrobank' else 'not on the cash sheet' end ||
       '. Add the row to the cash sheet and link it if it is missing there.', 'Loan sheet import'
from public.loan_schedule s join public.loans l on l.id = s.loan_id
where s.id like 'lsch-%' and s.due_date between date '2026-08-11' and date '2026-11-15' and s.loan_id <> 'loan-l300-siobal'
order by s.loan_id, s.seq
on conflict (id) do nothing;
-- L300 Siobal–Garcia: October and November are on the cash sheet (BPI). The
-- October row is labelled "UNIFORM - PRODUCTION STAFF" on the sheet; it is this loan.
insert into public.loan_payments (id, loan_id, entry_type, date, amount, principal, interest, bank, cash_key, cash_date, note, recorded_by) values
('lpay-imp-l300-siobal-01', 'loan-l300-siobal', 'payment', '2026-10-05', 21414, 21414, 0, 'bpi', '2026-10-05#out#bc733db6-6f3c-4ec7-a711-59a5e34ba025', '2026-10-05', 'Installment 1 (October). Cash-sheet row says "UNIFORM - PRODUCTION STAFF"', 'Loan sheet import'),
('lpay-imp-l300-siobal-02', 'loan-l300-siobal', 'payment', '2026-11-11', 21414, 21414, 0, 'bpi', '2026-11-11#out#e57dd71f-8672-4505-a89a-d62069ab7db3', '2026-11-11', 'Installment 2 (November)', 'Loan sheet import')
on conflict (id) do nothing;

